INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(45611, 'Zechariah 3:1', 'Zechariah', 3, 1, 'بيا هغۀ ما ته يشوَع مشر اِمام وښودلو چې د مالِک خُدائ د فرښتې په وړاندې ولاړ وو، او اِلزام لګوونکے يعنې شېطان د هغۀ په ښى طرف ولاړ وو چې په هغۀ اِلزام ولګوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah3_verse_1.mp3', '', 1761754199, 1761754199),
(45612, 'Zechariah 3:2', 'Zechariah', 3, 2, 'مالِک خُدائ شېطان ته وفرمائيل، ”مالِک خُدائ تا رټى، شېطانه. هغه مالِک خُدائ، چا چې يروشلم غوره کړے دے، هغه تا رټى. آيا دا سړے هغه سوزېدونکې لرګى په شان نۀ دے چې د اور نه راښکلے شوے وى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah3_verse_2.mp3', '', 1761754199, 1761754199),
(45613, 'Zechariah 3:3', 'Zechariah', 3, 3, 'اوس يشوَع په ګنده جامو کښې د فرښتې په مخکښې ولاړ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah3_verse_3.mp3', '', 1761754199, 1761754199),
(45614, 'Zechariah 3:4', 'Zechariah', 3, 4, 'فرښتې هغوئ ته وفرمائيل څوک چې د هغۀ د وړاندې ولاړ وُو، ”د دۀ نه ګنده جامې وباسئ.“ بيا هغې يشوَع ته وفرمائيل، ”وګوره، ما ستا ګناهونه لرې کړل، او زۀ به تا ته ښائسته جامې درواغوندم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah3_verse_4.mp3', '', 1761754199, 1761754199),
(45615, 'Zechariah 3:5', 'Zechariah', 3, 5, 'بيا ما ووئيل، ”هغوئ دې د هغۀ په سر باندې يو پاک پټکے کېږدى،“ او هغوئ ورته پاک پټکے په سر کېښودو او ښکلې نوې جامې يې ورواغوستلې کله چې لا د مالِک خُدائ فرښته د هغۀ سره هلته ولاړه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah3_verse_5.mp3', '', 1761754199, 1761754199),
(45616, 'Zechariah 3:6', 'Zechariah', 3, 6, 'د مالِک خُدائ فرښتې يشوَع له په کلکه وفرمائيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah3_verse_6.mp3', '', 1761754199, 1761754199),
(45617, 'Zechariah 3:7', 'Zechariah', 3, 7, '”دا هغه څۀ دى چې مالِک خُدائ ربُ الافواج فرمائى، کۀ تۀ زما په لار روان يې او زما قانون منې، نو تۀ به زما د کور حکمرانى کوې او زما د دربار اختيار به درسره وى، او زۀ به تا له د دوئ په مينځ کښې ځائ درکړم څوک چې دلته ولاړ دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah3_verse_7.mp3', '', 1761754199, 1761754199),
(45618, 'Zechariah 3:8', 'Zechariah', 3, 8, 'واوره، اے مشر اِمامه يشوَع او نور اِمامان چې ستا په وړاندې ناست دى، تاسو د راتلونکى ښۀ وخت نښه يئ، زۀ به خپل خِدمت کوونکے راولم چې څانګه بللے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah3_verse_8.mp3', '', 1761754199, 1761754199),
(45619, 'Zechariah 3:9', 'Zechariah', 3, 9, 'وګورئ، هغه قيمتى کاڼے چې ما د يشوَع په وړاندې اېښے دے. د هغه کاڼى اووۀ مخونه دى، او زۀ به په دې نقش وليکم، مالِک خُدائ ربُ الافواج فرمائى، او زۀ به د دې مُلک ګناهونه په يوه ورځ کښې ختم کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah3_verse_9.mp3', '', 1761754199, 1761754199),
(45620, 'Zechariah 3:10', 'Zechariah', 3, 10, 'په هغه ورځ به تاسو هر يو کس خپل ګاونډى راوغواړئ چې خپل د انګورو او اينځر د ونې لاندې کښېنئ، مالِک خُدائ ربُ الافواج فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah3_verse_10.mp3', '', 1761754199, 1761754199),
(45621, 'Psalms 51:1', 'Psalms', 51, 1, 'په خاطر ستا د تلپاتې مینې خدایه ما باندې رحم وکړه ستا د لوی رحمت په سبب له منځه یوسه ګناهونه زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_1.mp3', '', 1761754199, 1761754199),
(45622, 'Psalms 51:2', 'Psalms', 51, 2, 'ته زما ټولې بدۍ ووینځه او ما له خپلې ګناه پاک کړه ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_2.mp3', '', 1761754199, 1761754199),
(45623, 'Psalms 51:3', 'Psalms', 51, 3, 'کړم اعتراف یاغیتوبونو باندې تل یم خبر له خپلو ګناهونو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_3.mp3', '', 1761754199, 1761754199),
(45624, 'Psalms 51:4', 'Psalms', 51, 4, 'ستا مقابل کې مې ګناه کړې ده یوازې ستا په وړاندې څه چې د ستا په نظر بد وو ما هغه کړي دي نو ته په حقه یې زما د قضاوت په هکله حق په جانب یې ته زما د محکومیت په هکله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_4.mp3', '', 1761754199, 1761754199),
(45625, 'Psalms 51:5', 'Psalms', 51, 5, 'له پیدایښت څخه بدي موجود وه زما وجود کې د مور د ګېډې نه ګناه موجود وه زما بدن کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_5.mp3', '', 1761754199, 1761754199),
(45626, 'Psalms 51:6', 'Psalms', 51, 6, 'ته زمونږ په زړه کې حقیقت خوښوې ډکوې ذهن له حکمته زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_6.mp3', '', 1761754199, 1761754199),
(45627, 'Psalms 51:7', 'Psalms', 51, 7, 'لکه کاهن چې پاکوي خلک داسې پاک مې کړه په بوټي د وېلني ووینځه ما چې شمه سپین له واورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_7.mp3', '', 1761754199, 1761754199),
(45628, 'Psalms 51:8', 'Psalms', 51, 8, 'پرېږده چې وکړمه احساس د خوشحالۍ او خوښۍ که څه هم مات مې دي هډوکي ټکولی دې یم یوځلې بیا به زه خوشحاله شمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_8.mp3', '', 1761754199, 1761754199),
(45629, 'Psalms 51:9', 'Psalms', 51, 9, 'سترګې دې پټې کړه زما په ګناهونو باندې ټولې بدۍ زما له منځه یوسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_9.mp3', '', 1761754199, 1761754199),
(45630, 'Psalms 51:10', 'Psalms', 51, 10, 'په ما کې پاک زړه راپیدا کړه خدایه کړه راپیدا یو وفادار او نوی روح په ما کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_10.mp3', '', 1761754199, 1761754199),
(45631, 'Psalms 51:11', 'Psalms', 51, 11, 'له خپل حضور څخه دې مه شړه ما خپل سپېڅلی روح دې له ما مه وباسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_11.mp3', '', 1761754199, 1761754199),
(45632, 'Psalms 51:12', 'Psalms', 51, 12, 'یوځلې بیا دې د نجات خوشحالي راکړه ماته دې ته مې جوړ کړه چې د ستا اطاعت وکړمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_12.mp3', '', 1761754199, 1761754199),
(45633, 'Psalms 51:13', 'Psalms', 51, 13, 'نو بیا به زه وښایم ستا لار بدکارانو لره ګناهکاران بېرته را وبه ګرځي ستا لوري ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_13.mp3', '', 1761754199, 1761754199),
(45634, 'Psalms 51:14', 'Psalms', 51, 14, 'خدایه ما وژغوره د وینې تویولو له جرمه ای خدایه! زما نجات بخښونکی خدایه په خوشحالۍ به زه نېکي د ستا اعلان کړمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_14.mp3', '', 1761754199, 1761754199),
(45635, 'Psalms 51:15', 'Psalms', 51, 15, 'مرسته وکړه ته زما سره څښتنه چې بیان کړم ستا ثنا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_15.mp3', '', 1761754199, 1761754199),
(45636, 'Psalms 51:16', 'Psalms', 51, 16, 'په قربانۍ نه خوشحالېږې ته نو ځکه زه به هغه وړاندې نه کړم نه خوشحالېږې سوځېدونکو نذرانو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_16.mp3', '', 1761754199, 1761754199),
(45637, 'Psalms 51:17', 'Psalms', 51, 17, 'خدای ته چې غوره قرباني ده هغه مات روح دی سپک به نه ګڼې عاجز او توبه‌ګار زړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_17.mp3', '', 1761754199, 1761754199),
(45638, 'Psalms 51:18', 'Psalms', 51, 18, 'شه مهربانه په صهیون مرسته یې وکړه ته کاندي دېوالونه د اورشلیم چې دوباره ودان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_18.mp3', '', 1761754199, 1761754199),
(45639, 'Psalms 51:19', 'Psalms', 51, 19, 'بیا به راضي شې په سمو قربانیو باندې او سوځېدونکو نذرانو باندې قرباني به شي غویان ستا د قربانۍ ځای کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms51_verse_19.mp3', '', 1761754199, 1761754199),
(45640, 'Job 9:1', 'Job', 9, 1, 'نو ايُوب ورته په جواب کښې وفرمائيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_1.mp3', '', 1761754199, 1761754199),
(45641, 'Job 9:2', 'Job', 9, 2, '”په حقيقت کښې ما ته پته ده چې دا هم داسې ده، خو بنى آدم د خُدائ پاک په مخکښې څنګه صادق کېدے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_2.mp3', '', 1761754199, 1761754199),
(45642, 'Job 9:3', 'Job', 9, 3, 'کۀ يو کس د هغۀ سره لانجه کول وغواړى، نو هيڅ څوک به د هغۀ د زرګونو سوالونو نه د يو جواب هم ورنۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_3.mp3', '', 1761754199, 1761754199),
(45643, 'Job 9:4', 'Job', 9, 4, 'ځکه چې هغه زورَور او د حِکمت خاوند دے او څوک هم چې د هغۀ مخالفت کوى نو نقصان به اوچتوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_4.mp3', '', 1761754199, 1761754199),
(45644, 'Job 9:5', 'Job', 9, 5, 'هغه ناڅاپه غرونه خوځوى، او په غصه کښې يې تباه کوى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_5.mp3', '', 1761754199, 1761754199),
(45645, 'Job 9:6', 'Job', 9, 6, 'څوک چې په زمکه زلزله راولى، او د دې بنيادونه خوځوى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_6.mp3', '', 1761754199, 1761754199),
(45646, 'Job 9:7', 'Job', 9, 7, 'کۀ هغه حُکم وکړى نو نمر به راونۀ خېژى، او ستورى به ونۀ ځليږى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_7.mp3', '', 1761754199, 1761754199),
(45647, 'Job 9:8', 'Job', 9, 8, 'چا چې يواځې آسمانونه خوارۀ کړى دى چا چې د سمندر چپې ايسارې کړې دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_8.mp3', '', 1761754199, 1761754199),
(45648, 'Job 9:9', 'Job', 9, 9, 'چا چې ټول ستورى جوړ کړى دى، په دې کښې دب اکبر، جبار او ثريا او جنوبى ستورى هم شامل دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_9.mp3', '', 1761754199, 1761754199),
(45649, 'Job 9:10', 'Job', 9, 10, 'څوک چې د عقل نه بهر لوئ لوئ کارونه کوى، او بې‌شمېره عجيبه عجيبه کارونه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_10.mp3', '', 1761754199, 1761754199),
(45650, 'Job 9:11', 'Job', 9, 11, 'ګوره، هغه زما نه تېر شو، خو زۀ هغه نۀ وينم، هغه تېريږى، خو زۀ د هغۀ په تلو نۀ پوهېږم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_11.mp3', '', 1761754199, 1761754199),
(45651, 'Job 9:12', 'Job', 9, 12, 'چې هغه روح وباسى نو څوک يې منع کولے شى؟ څوک دا جرأت کولے شى چې ورته ووائى چې تۀ څۀ کوې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_12.mp3', '', 1761754199, 1761754199),
(45652, 'Job 9:13', 'Job', 9, 13, 'خُدائ پاک به د خپلې غصې نه نۀ اوړى، هغۀ سمندرى بلاګانې هم د پښې لاندې چخڼى کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_13.mp3', '', 1761754199, 1761754199),
(45653, 'Job 9:14', 'Job', 9, 14, 'نو زۀ څوک يم چې هغۀ له جواب ورکړم، او زۀ څوک يم چې د هغۀ سره بحث وکړم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_14.mp3', '', 1761754199, 1761754199),
(45654, 'Job 9:15', 'Job', 9, 15, 'اګر چې زۀ بې‌ګناه يم او زۀ هغۀ له جواب نۀ شم ورکولے، زۀ خپل قاضى ته صِرف د رحم درخواست کولے شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_15.mp3', '', 1761754199, 1761754199),
(45655, 'Job 9:16', 'Job', 9, 16, 'کۀ ما هغۀ ته آواز وکړو او هغۀ جواب راکړو، نو زما يقين نۀ دے چې هغه به زما فرياد واورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_16.mp3', '', 1761754199, 1761754199),
(45656, 'Job 9:17', 'Job', 9, 17, 'ځکه چې هغۀ زۀ په طوفان وهلے يم، او هغه بار بار ما زخمى کوى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_17.mp3', '', 1761754199, 1761754199),
(45657, 'Job 9:18', 'Job', 9, 18, 'هغه به ما ساه اخستو ته پرې نۀ ږدى، خو زما ژوند به د غمونو نه ډک کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_18.mp3', '', 1761754199, 1761754199),
(45658, 'Job 9:19', 'Job', 9, 19, 'کۀ دا د زور خبره وى، نو هغه طاقتور دے. کۀ دا د اِنصاف خبره وى، نو هغه عدالت ته څوک راغوښتے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_19.mp3', '', 1761754199, 1761754199),
(45659, 'Job 9:20', 'Job', 9, 20, 'اګر چې زۀ بې‌ګناه يم، خو زما خپله خولۀ به ما مجرم کړى، اګر چې زۀ بې‌داغه يم، خو خپله خولۀ به ما ګناهګار ثابِتوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_20.mp3', '', 1761754199, 1761754199),
(45660, 'Job 9:21', 'Job', 9, 21, 'زۀ بې‌داغه يم، زۀ خپل ځان هم نۀ پېژنم، زۀ خپل ژوند ته سپک ګورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_21.mp3', '', 1761754199, 1761754199),
(45661, 'Job 9:22', 'Job', 9, 22, 'ګناهګار او بې‌ګناه ټول د خُدائ پاک په نظر کښې يو شان دى نو ځکه زۀ وايم، هغه بې‌داغه او بدکاره دواړه تباه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_22.mp3', '', 1761754199, 1761754199),
(45662, 'Job 9:23', 'Job', 9, 23, 'کله چې افت ناڅاپه مرګ راولى، نو هغه د بې‌ګناه په غم پورې ټوقې کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_23.mp3', '', 1761754199, 1761754199),
(45663, 'Job 9:24', 'Job', 9, 24, 'ټوله دُنيا د بدکاره په لاس کښې ورکړے شوې ده، خُدائ پاک د قاضيانو سترګې پټوى، کۀ هغه دا نۀ کوى نو بيا يې څوک کوى، او دا څوک دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_24.mp3', '', 1761754199, 1761754199),
(45664, 'Job 9:25', 'Job', 9, 25, 'زما ژوند د منډه وهونکى نه تېز دے، دا په منډه روان دے او هيڅ خوشحالى ورته نۀ ملاويږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_25.mp3', '', 1761754199, 1761754199),
(45665, 'Job 9:26', 'Job', 9, 26, 'زما ژوند د تېزې کشتۍ په شان روان دے، داسې لکه چې باز په ښکار باندې غوټه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_26.mp3', '', 1761754199, 1761754199),
(45666, 'Job 9:27', 'Job', 9, 27, 'کۀ اراده وکړم چې خپل شکايت پرېږدم، نو زۀ به خپل خفګان په خوشحالۍ بدل کړم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_27.mp3', '', 1761754199, 1761754199),
(45667, 'Job 9:28', 'Job', 9, 28, 'زۀ د خپلو ټولو تکليفونو نه يرېږم، ځکه چې زۀ په دې پوهيږم چې تاسو به ما بې ګناه ونۀ ګڼئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_28.mp3', '', 1761754199, 1761754199),
(45668, 'Job 9:29', 'Job', 9, 29, 'چې زۀ مجرم ګڼلے شم، نو زۀ بيا بې‌فائدې خوارى ولې کوم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_29.mp3', '', 1761754199, 1761754199),
(45669, 'Job 9:30', 'Job', 9, 30, 'کۀ زۀ خپل ځان په واوره ووينځم او خپل لاسونه په صابون پاک کړم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_30.mp3', '', 1761754199, 1761754199),
(45670, 'Job 9:31', 'Job', 9, 31, 'خو تۀ به ما يوې ګنده کندې ته وروغورزوې، او زما خپلې جامې به زما نه نفرت کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_31.mp3', '', 1761754199, 1761754199),
(45671, 'Job 9:32', 'Job', 9, 32, 'هغه زما په شان فانى انسان نۀ دے، نو ځکه نۀ ورسره بحث کولے شم او نۀ يې د جرګې ځائ ته بوتلے شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_32.mp3', '', 1761754199, 1761754199),
(45672, 'Job 9:33', 'Job', 9, 33, 'زمونږ په مينځ کښې روغه کوونکے نشته، چې هغه زمونږ دواړو روغه جوړه وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_33.mp3', '', 1761754199, 1761754199),
(45673, 'Job 9:34', 'Job', 9, 34, 'کۀ مينځګړے ما د خُدائ پاک د سزا نه بچ کړى نو زۀ به بيا په يره کښې ژوند نۀ تېروم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_34.mp3', '', 1761754199, 1761754199),
(45674, 'Job 9:35', 'Job', 9, 35, 'بيا به زۀ ډاډه خبرې کوم چې د هغۀ يره زما په زړۀ کښې نۀ وى خو چې ترڅو پورې دا يره وى نو زۀ نۀ شم کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job9_verse_35.mp3', '', 1761754199, 1761754199),
(45675, 'Ezekiel 33:1', 'Ezekiel', 33, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_1.mp3', '', 1761754199, 1761754199),
(45676, 'Ezekiel 33:2', 'Ezekiel', 33, 2, '«ای فاني انسانه، خپلو خلکو ته ووایه: ‹که چېرې زه په یو هېواد باندې جنګ راولم او د هغه هېواد خلک د خپل منځ څخه یو کس د پهره‌دار په توګه وټاکي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_2.mp3', '', 1761754199, 1761754199),
(45677, 'Ezekiel 33:3', 'Ezekiel', 33, 3, 'کله چې هغه وویني چې دښمن راروان دی، نو هغه به سرنی ووهي چې خلک خبر کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_3.mp3', '', 1761754199, 1761754199),
(45678, 'Ezekiel 33:4', 'Ezekiel', 33, 4, 'که څوک د سرني اواز واوري او هېڅ پام ورته ونه کړي او دښمن راشي او هغه ووژني، نو خون به یې په خپله غاړه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_4.mp3', '', 1761754199, 1761754199),
(45679, 'Ezekiel 33:5', 'Ezekiel', 33, 5, 'ځکه چې هغه د سرني اواز واورېد، خو پام یې ورته ونه کړ، نو خون به یې په خپله غاړه وي. که چېرې هغه پام کړی وای، نو کولای یې شول چې خپل ځان وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_5.mp3', '', 1761754199, 1761754199),
(45680, 'Ezekiel 33:6', 'Ezekiel', 33, 6, 'خو که هغه پهره‌دار وګوري چې دښمن راروان دی او سرنی ونه وهي چې خلک خبر شي، نو دښمن به راشي او ځینې ګناهکاران به ووژني، خو زه به هغه پهره‌دار د هغوی د مرګ مسوول وګڼم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_6.mp3', '', 1761754199, 1761754199),
(45681, 'Ezekiel 33:7', 'Ezekiel', 33, 7, 'نو اوس ای فاني انسانه، ته مې د اسراییلو د قوم دپاره پهره‌دار ټاکلی یې. زه چې تاته کوم خبرداری درکوم باید هغوی ته یې ورسوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_7.mp3', '', 1761754199, 1761754199),
(45682, 'Ezekiel 33:8', 'Ezekiel', 33, 8, 'که زه یو بدکاره انسان ته خبرداری ورکړم چې هرومرو مړ کیږي او ته زما خبرداری هغه ته ونه رسوې او ورته ونه وایې چې د خپلو بدو کارونو څخه توبه وباسي، نو هغه به د خپلې ګناه له امله مړ شي، خو تا به د هغه د مړینې مسوول وګڼم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_8.mp3', '', 1761754199, 1761754199),
(45683, 'Ezekiel 33:9', 'Ezekiel', 33, 9, 'که چېرې ته هغه بدکاره انسان ته خبرداری ورکړې او هغه د خپلې ګناه نه لاس وانخلي، نو هغه به ګناهکار مړ شي، خو تا به د مرګ څخه خپل ځان ژغورلی وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_9.mp3', '', 1761754199, 1761754199),
(45684, 'Ezekiel 33:10', 'Ezekiel', 33, 10, 'څښتن ماته وویل: «ای فاني انسانه، اسراییلیانو ته ووایه چې تاسو داسې وایئ: ‹په مونږ باندې د خپلو سرکښیو او ګناهونو دروند بار پروت دی او مونږ یې کمزوري او ناتوانه کړي یو. نو مونږ به څنګه ژوندي پاتې شو؟›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_10.mp3', '', 1761754199, 1761754199),
(45685, 'Ezekiel 33:11', 'Ezekiel', 33, 11, 'هغوی ته ووایه چې زه څښتن تعالی داسې وایم: ‹زه په خپل ذات باندې قسم خورم چې زه د ګناهکار انسان په مرګ باندې نه خوشحالېږم، بلکې په دې خوشحالېږم چې هغه ګناه پرېږدي او ژوندی پاتې شي. ای اسراییلو، خپل بد کارونه پرېږدئ. تاسو ولې غواړئ چې مړه شئ؟›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_11.mp3', '', 1761754199, 1761754199),
(45686, 'Ezekiel 33:12', 'Ezekiel', 33, 12, 'نو ای فاني انسانه، اسراییلیانو ته ووایه کله چې یو نېک انسان ګناه وکړي، نو هغه چې کوم ښه کارونه کړي دي د هغو په سبب به د هغه ژوند ونه ژغورل شي. که یو بدعمله انسان د خپلو بدو نه لاس واخلي، نو هغه ته به سزا نه ورکول کیږي او که چېرې یو نېک انسان په ګناه کولو باندې پیل وکړي، نو هغه به د خپلو پخوانیو نېکو کارونو په خاطر ژوندی پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_12.mp3', '', 1761754199, 1761754199),
(45687, 'Ezekiel 33:13', 'Ezekiel', 33, 13, 'فرض کړئ چې زه د کوم نېک انسان سره وعده وکړم چې هغه به ژوندی پاتې شي، خو هغه په بدۍ کولو پیل وکړي او په دې فکر کې وي چې کوم نېک کارونه هغه مخکې کړي دي، د هغو په سبب به د هغه ژوند وژغورل شي، نو زه به د هغه نېک کارونه هېر کړم او هغه به د خپلو بدو کارونو له امله مړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_13.mp3', '', 1761754199, 1761754199),
(45688, 'Ezekiel 33:14', 'Ezekiel', 33, 14, 'فرض کړئ چې زه یو بدکاره انسان ته خبرداری ورکړم چې هغه به خامخا د خپلو ګناهونو په سبب مړ شي. خو که هغه ګناه کول پرېږدي او سم او نېک کارونه وکړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_14.mp3', '', 1761754199, 1761754199),
(45689, 'Ezekiel 33:15', 'Ezekiel', 33, 15, 'د مثال په ډول که چېرې هغه د ضمانت په توګه پور اخیستی وي او هغه بېرته ورکړي، یا هغه کوم شی غلا کړی وي او هغه بېرته ورکړي، د بدۍ نه لاس واخلي او د هغو قوانینو پیروي وکړي چې ژوندون ورکوي، نو هغه به نه مړ کیږي، بلکې ژوندی به پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_15.mp3', '', 1761754199, 1761754199),
(45690, 'Ezekiel 33:16', 'Ezekiel', 33, 16, 'هغه چې کومه ګناه کړې ده، هغه به ورته یاده نه کړم او هغه به خامخا ژوندی پاتې شي، ځکه چې سم او نېک کارونه یې کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_16.mp3', '', 1761754199, 1761754199),
(45691, 'Ezekiel 33:17', 'Ezekiel', 33, 17, 'خو ستا خلک وایي چې د څښتن لاره عادلانه نه ده! نه، د هغوی لاره عادلانه نه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_17.mp3', '', 1761754199, 1761754199),
(45692, 'Ezekiel 33:18', 'Ezekiel', 33, 18, 'کله چې یو نېک انسان د ښو کارونو نه لاس واخلي او بد کارونه پیل کړي، نو د هغو په سبب به هغه مړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_18.mp3', '', 1761754199, 1761754199),
(45693, 'Ezekiel 33:19', 'Ezekiel', 33, 19, 'کله چې کوم بدکاره انسان د ګناه نه لاس واخلي او عادلانه او نېک کارونه پیل کړي، نو هغه به ژوندی پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_19.mp3', '', 1761754199, 1761754199),
(45694, 'Ezekiel 33:20', 'Ezekiel', 33, 20, 'خو ای اسراییلو، تاسو وایئ چې د څښتن لاره عادلانه نه ده. زه به تاسو هر یو ستاسو د عمل سره سم محاکمه کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_20.mp3', '', 1761754199, 1761754199),
(45695, 'Ezekiel 33:21', 'Ezekiel', 33, 21, 'زمونږ د جلاوطنۍ د دولسم کال د لسمې میاشتې په پنځمه ورځ یو سړی چې د اورشلیم نه راتښتېدلی ؤ، راغی او ماته یې وویل: «ښار سقوط کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_21.mp3', '', 1761754199, 1761754199),
(45696, 'Ezekiel 33:22', 'Ezekiel', 33, 22, 'نو د ماښام په وخت کې مخکې له دې چې هغه سړی راشي، ما د څښتن قدرتمند حضور حس کړ. دا سړی د سهار په وخت راغی، خو د دې سړي د رارسېدلو څخه مخکې څښتن ماته بېرته د خبرو کولو توان راکړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_22.mp3', '', 1761754199, 1761754199),
(45697, 'Ezekiel 33:23', 'Ezekiel', 33, 23, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_23.mp3', '', 1761754199, 1761754199),
(45698, 'Ezekiel 33:24', 'Ezekiel', 33, 24, '«ای فاني انسانه، کوم خلک چې د اسراییلو په وران شویو ښارونو کې اوسیږي، هغوی وایي: ‹ابراهیم یوازې یو سړی ؤ او هغه ته ټول وطن ورکړل شو. نو څنګه چې زمونږ شمېر زیات دی، نو دا وطن باید زمونږ وي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_24.mp3', '', 1761754199, 1761754199),
(45699, 'Ezekiel 33:25', 'Ezekiel', 33, 25, 'هغوی ته ووایه چې زه څښتن تعالی هغوی ته داسې وایم: ‹تاسو داسې غوښه خورئ چې وینه لا په کې وي. تاسو د بتانو عبادت او قتلونه کوئ. نو بیا څنګه داسې فکر کوئ چې دا وطن ستاسو دی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_25.mp3', '', 1761754199, 1761754199),
(45700, 'Ezekiel 33:26', 'Ezekiel', 33, 26, 'تاسو په خپلو تورو باندې زړه تړلی دی. ستاسو عملونه د کرکې وړ دي. تاسو ټول د خپلو ګاونډیو د ښځو سره زنا کوئ. بیا څنګه داسې فکر کوئ چې دا وطن ستاسو دی؟›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_26.mp3', '', 1761754199, 1761754199),
(45701, 'Ezekiel 33:27', 'Ezekiel', 33, 27, 'هغوی ته ووایه چې زه څښتن تعالی هغوی ته داسې وایم: ‹زه په خپل ذات باندې قسم خورم، هغه خلک چې په ورانو ښارونو کې اوسیږي، هغوی به په جنګ کې ووژل شي. کوم خلک چې په صحرا کې اوسیږي، نو ځنګلي حیوانات به پرېږدم چې هغوی وخوري. کوم خلک چې په غرونو او غارونو کې اوسیږي، هغوی به د وبا له لاسه مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_27.mp3', '', 1761754199, 1761754199),
(45702, 'Ezekiel 33:28', 'Ezekiel', 33, 28, 'زه به دا وطن وران او ویجاړ کړم او د هغوی هغه قدرت به له منځه لاړ شي چې هغوی ورباندې مغروره وو. د اسراییلو غرونه به داسې وران شي چې هېڅوک به ورباندې تګ او راتګ نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_28.mp3', '', 1761754199, 1761754199),
(45703, 'Ezekiel 33:29', 'Ezekiel', 33, 29, 'کله چې زه خلکو ته د هغوی د کرکې وړ کارونو په سبب سزا ورکړم او هغه وطن وران او ویجاړ کړم، نو بیا به هغوی پوه شي چې زه څښتن یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_29.mp3', '', 1761754199, 1761754199),
(45704, 'Ezekiel 33:30', 'Ezekiel', 33, 30, 'څښتن وویل: «ای فاني انسانه، کله چې خلک د ښار د دېوالونو او د خپلو کورونو په دروازو کې سره راټولیږي، نو ستا په هکله خبرې کوي. هغوی یو بل ته وایي: ‹راځئ چې لاړ شو او هغه کلام واورو چې د څښتن له خوا راغلی دی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_30.mp3', '', 1761754199, 1761754199),
(45705, 'Ezekiel 33:31', 'Ezekiel', 33, 31, 'نو زما قوم راټولیږي او ستا خبرو ته غوږ نیسي، خو په هغو باندې عمل نه کوي. ځکه هغوی د چاپلوسۍ خبرې کوي، خو هغوی یوازې خپلو ګټو پسې ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_31.mp3', '', 1761754199, 1761754199),
(45706, 'Ezekiel 33:32', 'Ezekiel', 33, 32, 'ګوره، د هغوی دپاره ته یوازې یو سندرغاړی یې چې په خپل ښکلي اواز سره عشقي سندرې وایې او ښه ساز غږوې. هغوی ستا خبرو ته غوږ نیسي، خو په هغو باندې عمل نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_32.mp3', '', 1761754199, 1761754199),
(45707, 'Ezekiel 33:33', 'Ezekiel', 33, 33, 'خو کله چې ستا خبرې رښتیا شي او هغه به بې له شکه رښتیا شي، بیا به هغوی پوه شي چې د هغوی په منځ کې یو پیغمبر ؤ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel33_verse_33.mp3', '', 1761754199, 1761754199),
(45708, 'Deuteronomy 4:1', 'Deuteronomy', 4, 1, 'بیا موسی خلکو ته وویل: «د هغو ټولو قوانینو اطاعت وکړئ چې زه یې تاسو ته درزده کوم، ترڅو تاسو ژوندي پاتې شئ او هغې ځمکې ته به ورننوځي او وبه یې نیسئ چې ستاسو د نیکونو څښتن خدای یې درکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_1.mp3', '', 1761754199, 1761754199),
(45709, 'Deuteronomy 4:2', 'Deuteronomy', 4, 2, 'زما امرونو ته هېڅ شی ورزیات او هېڅ شی ورڅخه کم نه کړئ. د خپل څښتن خدای د امرونو څخه چې ما درکړي دي، اطاعت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_2.mp3', '', 1761754199, 1761754199),
(45710, 'Deuteronomy 4:3', 'Deuteronomy', 4, 3, 'تاسو په خپله ولیدل چې څښتن د فغور غره ته نژدې څه وکړل. څښتن هغه ټول خلک له منځه یووړل چې هلته یې د بعل د بت عبادت کاوه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy4_verse_3.mp3', '', 1761754199, 1761754199);